local ActivityGachaponTowerEntryDialog = Class('ActivityGachaponTowerEntryDialog')
local Count = 3
local MaxLayer = 6
local ActivityGachaponTowerMgr = import('Game.Activity.GachaponTower.ActivityGachaponTowerMgr')

function ActivityGachaponTowerEntryDialog:__init()
    self.activityData = nil
end

function ActivityGachaponTowerEntryDialog:__delete()
    self.activityData = nil
end

function ActivityGachaponTowerEntryDialog:Awake()
    self:AddUIClick()
    self:InitComponent()
end

function ActivityGachaponTowerEntryDialog:InitComponent()
    for i = 1, Count do
        local go
        if i == 1 then
            go = self.DescNode
        else
            go = CS.UnityEngine.GameObject.Instantiate(self.DescNode.gameObject)
            KTool.SetParent(go,self.GachaponDesc.gameObject,false)
        end

        local env = CfUtils.GetLuaScr(go,"Game.Activity.GachaponTower.Cell.ActivityGachaponTowerDescCell")
        if isNotNull(env) then
            env:Refresh(i)
        end
    end

    CfUtils.SetActive(self.BtnSkipAnimation.gameObject,false)
end

function ActivityGachaponTowerEntryDialog:AddUIClick()
    SetButtonAction(self.BtnExplain.gameObject,Bind(self,self.OnBtnExplainClick))
    SetButtonAction(self.BtnSkipAnimation.gameObject,Bind(self,self.OnBtnSkipAnimationClick))
    SetButtonAction(self.BtnGachapon.gameObject,Bind(self,self.OnBtnGachaponClick))
end

function ActivityGachaponTowerEntryDialog:OnBtnExplainClick()
    local ruleId = checkNumber(self.serverData.activityConfig.ruleId)
    if ruleId > 0 then
        CfUtils.ShowModuleToast(self.serverData.activityConfig.ruleId)
    end
end

function ActivityGachaponTowerEntryDialog:OnBtnSkipAnimationClick()
    local isJump = self:IsJumpAni()
    local key = self:GetJumpAniKey()
    CfUtils.WriteLocalData(key,isJump and 0 or 1)
    self:SetIsJumpAni()
end

---开始抽奖
function ActivityGachaponTowerEntryDialog:OnBtnGachaponClick()
    local isEnd = self:IsEnd()
    if isEnd then
        GameUtils.Toast("抽奖已全部完成")
        return
    end

    local isNeedSelect = self:IsSelectChoose()
    if isNeedSelect then
        GameUtils.Toast(localize("请先选择自选奖励"))
        return
    end

    local isEnough = self:IsCurrencyEnough()
    if not isEnough then
        GoodsUtils.CheckConsumeDataCondition(self.serverData.nextConsume)
        return
    end

    GameUtils.Request(Interfaces.ActivityMeowLuckDraw,{activityUuid = self.activityData.id },function(request, response)
        if checkNumber(response.errCode) == 0 then
            local responseData = response.data
            local rewards = responseData.rewards
            GoodsUtils.DrawRewards({ { goodsId = self.serverData.nextConsume[1].goodsId, num = - self.serverData.nextConsume[1].num } }, true)
            local isSkipAni = self:IsJumpAni()
            local index = self:GetCurRewardIndex(responseData.rewardId)
            if isSkipAni or self.serverData.drawInfo.layer == MaxLayer then
                if isSet(responseData,"bigRewards") and table.count(checkTable(responseData.bigRewards)) > 0 then
                    self:DrawBigReward(responseData)
                else
                    self:DrawRewardEnd(rewards, responseData)
                end

            else
                local env = self:GetRewardRootEnv()
                if env then
                    if checkNumber(index) > 0 then
                        env:StartAnimation(index, self.serverData.drawInfo.layer, nil,function()
                            if isSet(responseData,"bigRewards") and table.count(checkTable(responseData.bigRewards)) > 0 then
                                self:DrawBigReward(responseData)
                            else
                                self:DrawRewardEnd(rewards, responseData)
                            end
                        end)
                    end
                end
            end
        end
    end)
end

function ActivityGachaponTowerEntryDialog:DrawBigReward(responseData)
    GoodsUtils.DrawRewards(responseData.bigRewards, true)
    CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.bigRewards , cb = function()
        self:DrawRewardEnd(responseData.rewards,responseData)
    end } })

end

function ActivityGachaponTowerEntryDialog:GetCurRewardIndex(rewardId)
    local rewards = self.serverData.nowRoundRewards
    for i, v in ipairs(rewards[self.serverData.drawInfo.layer]) do
        if v.id == rewardId then
            return i
        end
    end
    return nil
end

function ActivityGachaponTowerEntryDialog:DrawRewardEnd(rewards, responseData)
    if table.count(rewards) > 0 then
        GoodsUtils.DrawRewards(rewards, true)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards , cb = function()
            ---层数切换  要播放动画
            local layer = self.serverData.drawInfo.layer
            local env = self:GetRewardRootEnv()
            if responseData.drawInfo.layer ~= layer then
                env:RefreshLayerShow(responseData.drawInfo.layer)
            end
            ActivityGachaponTowerMgr:GetInstance():UpdateServerData(responseData)
            self:RefreshShow(true)
        end } })
    else

    end
end

function ActivityGachaponTowerEntryDialog:IsSelectChoose()
    local isNeedSelect = false
    local rewards = self.serverData.nowRoundRewards
    for i, v in ipairs(rewards[self.serverData.drawInfo.layer]) do
        if v.isChoose == 1 and not self.serverData.chooseRewardLocation[tostring(v.id)] then
            isNeedSelect = true
            break
        end
    end
    return isNeedSelect
end

function ActivityGachaponTowerEntryDialog:IsCurrencyEnough()
    local currencyInfo = self.serverData.nextConsume[1]
    return GoodsUtils.GetThingNo(currencyInfo.goodsId) >= currencyInfo.num
end

function ActivityGachaponTowerEntryDialog:Refresh(data)
    self.activityData = data
    ActivityGachaponTowerMgr:GetInstance():SaveActivityData(data)
    self:SetTitle()
    self:SetTimeShow()
    self:SetIsJumpAni()
    self:RequestShow()
end

function ActivityGachaponTowerEntryDialog:RefreshNavBar()
    CfUtils.RefreshTopGoods({ self.serverData.nextConsume[1].goodsId})
end

function ActivityGachaponTowerEntryDialog:RequestShow()
    GameUtils.Request(Interfaces.ActivityMeowHighTea,{ activityUuid = self.activityData.id },function(request,response)
        if checkNumber(response.errCode) == 0 then
            local responseData = response.data
            self.serverData = responseData
            ActivityGachaponTowerMgr:GetInstance():SyncServerData(responseData)
            self:RefreshShow()
        end
    end)
end

function ActivityGachaponTowerEntryDialog:RefreshShow(ignore)
    self:SetRoundShow()
    self:SetGetAllReward()
    self:SetDrawCost()
    self:SetRewardRootShow(ignore)
    self:RefreshNavBar()
    self:SetJumpAniBtnShow()
end

function ActivityGachaponTowerEntryDialog:SetRewardRootShow(ignore)
    local env = self:GetRewardRootEnv()
    env:SetCurLayer(self.serverData.drawInfo.layer)
    env:RefreshShow(self.serverData.nowRoundRewards, self.serverData.chooseRewardLocation, ignore)
end

function ActivityGachaponTowerEntryDialog:GetRewardRootEnv()
    if isNull(self.RewardEnv) then
        local env = CfUtils.GetLuaScr(self.RewardRoot,"Game.Activity.GachaponTower.ActivityGachaponTowerEntryRoot")
        if not isNull(env) then
            self.RewardEnv = env
        end
    end
    return self.RewardEnv
end

function ActivityGachaponTowerEntryDialog:SetDrawCost()
    local isEnd = self:IsEnd()
    if isEnd then
        return
    end
    local env = CfUtils.GetLuaScr(self.BtnGachapon,"Game.Behaviours.CommonCurrencyNode")
    if not isNull(env) then
        local currencyInfo = self.serverData.nextConsume[1]
        if isNotNull(currencyInfo) then
            env:SetCurrencyShow(currencyInfo.goodsId,nil,"x"..currencyInfo.num)
        end
    end
end

function ActivityGachaponTowerEntryDialog:IsEnd()
    return checkNumber(self.serverData.drawInfo.isEnd)  == 1
end

function ActivityGachaponTowerEntryDialog:SetGetAllReward()
    local isGetAll = self:IsEnd()
    CfUtils.SetActive(self.FInish.gameObject,isGetAll)
    CfUtils.SetActive(self.Underway.gameObject,not isGetAll)
end

function ActivityGachaponTowerEntryDialog:SetIsJumpAni()
    local isJump = self:IsJumpAni()
    CfUtils.SetActive(self.ImgSymbol2, isJump)
end

function ActivityGachaponTowerEntryDialog:SetJumpAniBtnShow()
    local count = checkNumber(self.serverData.drawInfo.luckDrawNum)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6436,"ActivityMeowParams",3)
    if count >= checkNumber(vo.num) then
        CfUtils.SetActive(self.BtnSkipAnimation.gameObject,true)
    else
        CfUtils.SetActive(self.BtnSkipAnimation.gameObject,false)
    end
end

function ActivityGachaponTowerEntryDialog:IsJumpAni()
    local key = self:GetJumpAniKey()
    local isJump = CfUtils.GetLocalData(key,0)
    return checkNumber(isJump) == 1
end

function ActivityGachaponTowerEntryDialog:GetJumpAniKey()
    return table.concat({"ActivityGachaponTowerJumpAni_",self.activityData.id})
end

function ActivityGachaponTowerEntryDialog:SetRoundShow()
    CfUtils.FillText(self.RoundNum,self.serverData.drawInfo.round.."/"..self.serverData.countRound)
end

function ActivityGachaponTowerEntryDialog:SetTimeShow()
    --region 时间
    local startTime =  self.activityData.startTime
    local closeTime =  self.activityData.closeTime
    local ActivityUtils         = import("Game.Activity.ActivityUtils")
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
end

function ActivityGachaponTowerEntryDialog:SetTitle()
    local titleImgUrl = checkString(self.activityData.titleImage)
    if string.len(titleImgUrl) > 0 then
        CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
    end
end

function ActivityGachaponTowerEntryDialog:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActivityGachaponTowerEntryDialog